// fx 축약 표기(모듈 로드 시 객체로 변환): 'W+3 P-2 #job+4 $d+500'
//   지표 H건강 I지력 P행복 W재산감 R관계 L여가 / #이슈키 / $a 자산 $d 부채(만 원).
const SK = { H: 'health', I: 'intellect', P: 'happiness', W: 'wealth', R: 'relations', L: 'leisure' };
export const fx = s => {
  const o = {};
  for (const t of (s || '').split(/\s+/).filter(Boolean)) {
    const m = /^(#[a-z]+|\$[ad]|[HIPWRL])([+-]\d+)$/.exec(t);
    if (!m) throw new Error(`fx 표기 오류: ${t}`);
    const [, k, v] = m, n = Number(v);
    if (k[0] === '#') (o.issues ??= {})[k.slice(1)] = n;
    else if (k[0] === '$') (o.money ??= {})[k === '$a' ? 'assets' : 'debt'] = n;
    else (o.stats ??= {})[SK[k]] = n;
  }
  return o;
};
// era([[시작연도, 문장], …]) → (L) => 문장
const E = rows => L => { const y = L?.year ?? 2000; let t = rows[0][1]; for (const [f, s] of rows) if (y >= f) t = s; return t; };
const job = L => L?.job?.status;
const working = L => job(L) === 'employed' || job(L) === 'self';
const debtor = L => (L?.money?.debt ?? 0) > 0;

